export default {
  data() {
    return {
      loading: false,
      otherIndus: 0,
      employeCount: "",
      selectedCard: "",
      secondStepData: {},
      selectedRange: "",
      selectedStyle: {
        backgroundColor: "#E3F2FD",
        // Blue shade for selected
        color: "black",
        borderColor: "#42A5F5"
      },
      defaultStyle: {
        backgroundColor: "white",
        color: "black",
        borderColor: "#ccc"
      },
      softwareDeveloperImg,
      securityUpdateImg,
      lifeInsuranceImg,
      processImg,
      workerImg,
      outletsImg,
      healthyDrinkImg,
      hospitalityImg
